function validate([bottom, allowed]) {
  if (typeof bottom !== 'string' || bottom.length < 2 || bottom.length > 6) return 'bottom needs 2 to 6 letters.';
  if (!/^[A-F]+$/.test(bottom)) return 'bottom may only use the letters A to F.';
  if (!Array.isArray(allowed) || allowed.length > 216) return 'allowed holds at most 216 patterns.';
  for (const pattern of allowed) {
    if (typeof pattern !== 'string' || !/^[A-F]{3}$/.test(pattern)) return 'Each pattern is three letters from A to F.';
  }
  if (new Set(allowed).size !== allowed.length) return 'The patterns in allowed must be distinct.';
  return null;
}

