function pyramidTransition(bottom, allowed) {
  const tops = new Map();
  for (const pattern of allowed) {
    const pair = pattern.slice(0, 2);
    if (!tops.has(pair)) tops.set(pair, []);
    tops.get(pair).push(pattern[2]);
  }
  const failed = new Set();
  const solve = row => {
    if (row.length === 1) return true;
    if (failed.has(row)) return false;
    const ok = fill(row, '');
    if (!ok) failed.add(row);
    return ok;
  };
  const fill = (row, next) => {
    if (next.length === row.length - 1) return solve(next);
    const pair = row[next.length] + row[next.length + 1];
    const options = tops.get(pair) || [];
    for (const block of options) {
      if (fill(row, next + block)) return true;
    }
    return false;
  };
  return solve(bottom);
}

