function pyramidTransition(bottom, allowed) {
  // Plain search without memory: list every possible next row, then try each one in turn.
  const allowedSet = new Set(allowed);
  const letters = ['A', 'B', 'C', 'D', 'E', 'F'];
  const nextRows = row => {
    let rows = [''];
    for (let i = 0; i + 1 < row.length; i++) {
      const grown = [];
      for (const partial of rows) {
        for (const letter of letters) {
          if (allowedSet.has(row[i] + row[i + 1] + letter)) grown.push(partial + letter);
        }
      }
      rows = grown;
    }
    return rows;
  };
  const canFinish = row => row.length === 1 || nextRows(row).some(canFinish);
  return canFinish(bottom);
}

