function generate(rand, size) {
  const letters = ['A', 'B', 'C', 'D', 'E', 'F'];
  const pick = n => Math.floor(rand() * n);
  let alphabet;
  let length;
  let density;
  if (size === 'large') {
    alphabet = letters.slice();
    length = 6;
    density = 0.08 + rand() * 0.42;
  } else {
    const count = 2 + pick(3);
    alphabet = letters.slice().sort(() => rand() - 0.5).slice(0, count);
    length = 2 + pick(count === 2 ? 5 : count === 3 ? 4 : 3);
    density = 0.15 + rand() * 0.6;
  }
  let bottom = '';
  for (let i = 0; i < length; i++) bottom += alphabet[pick(alphabet.length)];
  const allowed = [];
  for (const x of alphabet) for (const y of alphabet) for (const z of alphabet) {
    if (rand() < density) allowed.push(x + y + z);
  }
  for (let i = allowed.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [allowed[i], allowed[j]] = [allowed[j], allowed[i]];
  }
  return [bottom, allowed];
}
